#!/usr/bin/env bash
# Generates development secrets on first run. Never overwrites existing files.
# Output (all git-ignored): dev/.env, dev/secrets/master.key, dev/secrets/certs/
#
# master.key format (one key per line): <key-id> <current|decrypt-only> <base64 of 32 random bytes>
set -euo pipefail
cd "$(dirname "$0")/../.."
umask 077

random_token() { od -An -N24 -tx1 /dev/urandom | tr -d ' \n'; }

mkdir -p dev/secrets
mkdir -p dev/secrets/certs
chmod 755 dev/secrets/certs

if [ ! -f dev/.env ]; then
  cat > dev/.env <<ENV
# Generated by dev-init.sh. Do not commit. Delete this file (just dev-reset) to regenerate.
TANDEM_DEV_DB_PORT=5432
POSTGRES_PASSWORD=$(random_token)
TANDEM_MIGRATE_PASSWORD=$(random_token)
TANDEM_APP_PASSWORD=$(random_token)
TANDEM_METRICS_TOKEN=$(random_token)
ENV
  echo "created dev/.env"
else
  echo "dev/.env already exists; keeping it"
fi

if [ ! -f dev/secrets/master.key ]; then
  printf 'dev-1 current %s\n' "$(head -c 32 /dev/urandom | base64 -w0)" > dev/secrets/master.key
  echo "created dev/secrets/master.key"
else
  echo "dev/secrets/master.key already exists; keeping it"
fi

chmod 600 dev/.env dev/secrets/master.key
echo "next: just dev-up (creates certificates on first start), then just migrate"
